Важно: граница лимита включающая: issuedToday + qty <= limit — разрешено, issuedToday + qty > limit — отказ.", "change":"Создать файл src/issue-limits.ts со следующим содержимым:

/**
 * Дневные лимиты выдачи из склада. Комментарий к каждому значению описывает причину (пример: 'Физический лимит рабочих рук и рампы на складе').
 */
import type { Warehouse } from './stock.ts';
import { findEntry } from './stock.ts';

export type IssueResult = { ok: true } | { ok: false; reason: string };

/**
 * Дневной лимит выдачи в штуках для каждого склада.
 * Комментарий — причина лимита.
 */
export const DAILY_ISSUE_LIMIT: Readonly<Record<Warehouse, number>> = {
  'wh-msk': 100, // 'Физический лимит рабочих рук и рампы на складе wh-msk',
  'wh-spb': 60,  // 'Физический лимит рабочих рук и рампы на складе wh-spb',
  'wh-ekb': 40,  // 'Физический лимит рабочих рук и рампы на складе wh-ekb',
  'wh-vld': 25,  // 'Физический лимит рабочих рук и рампы на складе wh-vld',
};

/**
 * Определяет, можно ли выдать `qty` штук позиции `sku` на складе `warehouse`,
 * учитывая уже выданные сегодня `issuedToday` штуки.
 */
export function issue(
  warehouse: Warehouse,
  sku: string,
  qty: number,
  issuedToday: number,
): IssueResult {
  // Проверка наличия позиции
  const entry = findEntry(warehouse, sku);
  if (entry === null) {
    return { ok: false, reason: `позиции ${sku} на складе ${warehouse} нет` };
  }

  // Проверка дневного лимита: issuedToday + qty <= лимит (ровно лимит — разрешено)
  const limit = DAILY_ISSUE_LIMIT[warehouse];
  if (issuedToday + qty > limit) {
    return {
      ok: false,
      reason: `dailyIssueLimit; warehouse=${warehouse}, limit=${limit}, issuedToday=${issuedToday}, qty=${qty}`;
    };
  }

  // Иначе — выдача разрешена (дублирование проверки резерва не нужно — reserve уже проверяет резерв)
  return { ok: true };
}

